        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'mean': 13.0, 'max': 16, 'grade': 'low'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 16.666666666666668, 'max': 24, 'grade': 'low'})
